    if ((uintptr_t)config->state_block % descriptor.alignment) return ORPHEUS_ERR_INVALID_ARG;
    orpheus_builtin_bulk_relay_Parameters candidate; int result=configure_parameters(&candidate, config);
    if (result!=ORPHEUS_OK) return result;
    orpheus_builtin_bulk_relay_State* s=(orpheus_builtin_bulk_relay_State*)config->state_block;
    memset(s, 0, sizeof(*s)); commit_parameters(s, &candidate);
