        return ORPHEUS_ERR_INVALID_ARG;
    io.out.delivery=(OrpheusDelivery){.buffer=NULL,.frame_index=ctx->frame_index,
        .epoch=ctx->epoch,.timeline_flags=ctx->timeline_flags};
